{
  "hypotheses": [
    {
      "claim": "pWaitFor rejects with a generic Error instead of TimeoutError when a numeric timeout expires, violating the contract to reject with TimeoutError.",
      "path": "index.js",
      "start_line": 57,
      "end_line": 69,
      "evidence": "throw new TimeoutError();",
      "reproduction": {
        "code": "const {default: pWaitFor, TimeoutError} = await load('./index.js');\ntry {\n  await pWaitFor(() => false, {timeout: 10, interval: 5});\n  assert.fail('Should have thrown');\n} catch (error) {\n  assert.ok(error instanceof TimeoutError, `Expected TimeoutError, got ${error.constructor.name}`);\n}"
      }
    }
  ]
}
